T1 = ('引き出しの奥から、古い腕時計が出てきた。止まったままの針を見ていると、あの夏のことが思い出された。\n'
      '小学四年の夏、ぼくは祖父の家にあずけられた。祖父は口数が少なく、ぼくはどう話しかけてよいかわからなかった。ある夕方、縁側で時計の修理をしている祖父のそばに座ると、祖父は黙って小さなねじを一つ、ぼくの手のひらにのせた。「なくすなよ。」それだけだった。けれど、そのねじの重さが、なぜだかとてもうれしかった。\n'
      'あれから五年がたった。ぼくは時計を手に取り、そっとねじを巻いてみた。')
T2 = ('マラソン大会の朝、空は重たい灰色の雲におおわれていた。美咲はスタートラインで、何度もくつひもを結び直した。去年は途中で歩いてしまい、ゴールしたときには、もうだれも残っていなかったのだ。\n'
      '号砲が鳴った。最初の坂で、もう息が苦しくなった。そのとき、沿道から「美咲、いけ！」という声が聞こえた。ふり向くと、去年いっしょに歩いた由香が、手をふっていた。美咲は前を向き、腕を大きくふった。\n'
      'ゴールテープを切ったとき、雲のすき間から日の光がさしこんでいた。')
T3 = ('「どうせ無理だよ。」健太はそう言って、ノートを閉じた。夏休みの自由研究のテーマが決まらないのだ。\n'
      '「無理かどうか、やってみないとわからないじゃない。」姉はそう言うと、台所から小さなびんを持ってきた。「これに、庭の土を入れてごらん。毎日、水をあげるの。」\n'
      '一週間後、びんの中から、小さな芽が顔を出していた。健太はノートを開き、えんぴつを走らせた。')
T4 = ('放課後の図書室には、いつも同じ席に座る三年生がいた。名札には「高橋」とある。陽菜は、その先輩が読む本の題名を、こっそりメモするのが楽しみだった。\n'
      'ある日、先輩の席に一冊の本が置き忘れられていた。陽菜がそれを返そうと手に取ると、しおりの代わりにはさまれていた紙に、陽菜の好きな作家の名前がずらりと並んでいた。\n'
      '次の日、陽菜は思い切って声をかけた。「この本、好きなんですか。」先輩は少しおどろいて、それから照れくさそうに笑った。')
def H(t, title): return f'次の文章（Claudeが作った物語「{title}」）を読んで答えよう。\n' + t.replace('\n', '\n　') + '\n'
P1, P2, P3, P4 = H(T1, '腕時計'), H(T2, '坂の上の光'), H(T3, '小さな芽'), H(T4, '図書室の先輩')
u.strip = (P1, P2, P3, P4)
T5 = ('九回裏、二死満塁。マウンドの翔太は、汗でぬれたボールをにぎりしめた。ベンチからの声も、もう耳に入らない。翔太は一度目を閉じ、去年の夏、同じ場面で打たれたことを思い出した。あのとき、捕手の大地は何も言わずに肩をたたいてくれた。\n'
      '目を開けると、大地がミットを胸の前で小さく二回たたいていた。去年と同じ合図だった。翔太の肩から、ふっと力がぬけた。\n'
      '投げたボールは、まっすぐミットに吸いこまれた。')
T6 = ('【姉】妹の誕生日に、わたしは手作りのケーキを焼いた。形はくずれてしまい、テーブルに出すのがはずかしかった。\n'
      '【妹】お姉ちゃんのケーキは、少し形がくずれていた。でも、わたしのために夜おそくまで台所に立っていたことを、わたしは知っていた。')
P5, P6 = H(T5, '最後の一球'), H(T6, '誕生日のケーキ')
u.strip = (P1, P2, P3, P4, P5, P6)
def NUK(text, ans):
    # 書き抜きの答えが本文に一か所だけあることを確かめる
    flat = text.replace('\n', '')
    assert flat.count(ans) == 1, (ans, flat.count(ans))
    return [ans]

